import java.util.*;

public class Main {
    static List<Integer> selfDividingNumbers(int left, int right) {
        List<Integer> result = new ArrayList<>();
        for (int num = left; num <= right; num++) {
            boolean ok = true;
            for (char ch : String.valueOf(num).toCharArray()) {  // convert to a string, then inspect each character
                int digit = ch - '0';
                if (digit == 0 || num % digit != 0) { ok = false; break; }
            }
            if (ok) result.add(num);
        }
        return result;
    }
}

