def self_dividing_numbers(left, right):
    result = []
    for num in range(left, right + 1):
        n, ok = num, True
        while n > 0:
            digit = n % 10                        # last digit, no string needed
            if digit == 0 or num % digit != 0:
                ok = False
                break
            n //= 10                                # remove that digit
        if ok:
            result.append(num)
